const marketPhotoQueries={'Семена':'seeds,plant','Рассада':'seedling,plant','Овощи':'vegetables,harvest','Полив':'irrigation,garden','Обустройство':'garden,raised-bed'};
const marketPhotoIds={'Семена':'photo-1416879595882-3373a0480b5b','Рассада':'photo-1416879595882-3373a0480b5b','Овощи':'photo-1540420773420-3366772f4999','Полив':'photo-1416879595882-3373a0480b5b','Обустройство':'photo-1416879595882-3373a0480b5b'};
function marketDescription(p){const v=Number(p.id.split('-')[2]);if(p.category==='Семена')return `Посевной материал для грядки. ${[1,3,5][v]} пакет${v===0?'':v===1?'а':'ов'} в демонстрационном наборе. Сорт, всхожесть и срок годности уточняются при реальном предложении.`;if(p.category==='Рассада')return `Набор из ${[4,8,12][v]} молодых растений для высадки. Подбор под сезон и условия грядки. Возраст и готовность к пересадке подтверждает ферма.`;if(p.category==='Овощи')return 'Цена за 1 кг. Овощи для домашней корзины, самовывоза или подарка. Сорт, дата сбора, качество и срок хранения указываются в паспорте реальной партии.';if(p.category==='Полив')return `${p.name.split(' · ')[0]} для ухода за посадками. ${p.rent?'Демонстрационная аренда на месяц.':'Продажа комплекта.'} Размер, давление, подключение и совместимость согласуются перед заказом; установка отдельно.`;return `${p.name.split(' · ')[0]} для обустройства грядки. ${p.rent?'Аренда на один месяц.':'Цена за комплект.'} Размер, материал и состав уточняются под участок; монтаж и доставка отдельно.`}
const marketBeforePhotos=demoMarketPage;demoMarketPage=function(){const html=marketBeforePhotos();const box=document.createElement('div');box.innerHTML=html;const products=demoCatalog.filter(p=>(demoMarketFilter==='Все'||p.category===demoMarketFilter)&&p.name.toLowerCase().includes(demoMarketSearch.toLowerCase()));box.querySelectorAll('.grid>article').forEach((card,i)=>{const p=products[i];if(!p)return;card.classList.add('market-photo-card');card.querySelector('span').remove();const photo=document.createElement('div');photo.className='market-product-photo';photo.innerHTML=`<img src="https://images.unsplash.com/${marketPhotoIds[p.category]}?auto=format&fit=crop&w=640&q=75" alt="Иллюстрация категории ${esc(p.category)}" loading="lazy" referrerpolicy="no-referrer"><span>Фото категории · демо</span>`;card.prepend(photo);const paragraphs=card.querySelectorAll('p');paragraphs[0].classList.add('market-product-price');paragraphs[1].textContent=marketDescription(p);paragraphs[1].classList.add('market-product-description')});return box.innerHTML};render();
